"""Embed the Aurebesh AF Canon font as a Lua module (UI-02).

An HTML widget is its own page, so the font travels inside the markup as a
base64 data URI. Writes src/widgets/lotj-ui-font.lua from assets/fonts.
Usage: python scripts/ui/embed_font.py [--check]
"""
import base64
import pathlib
import sys

ROOT = pathlib.Path(__file__).resolve().parents[2]
FONT = ROOT / "assets" / "fonts" / "AurebeshAF-Canon.otf"
OUT = ROOT / "src" / "widgets" / "lotj-ui-font.lua"


def render():
    data = base64.b64encode(FONT.read_bytes()).decode("ascii")
    return (
        "-- Generated by scripts/ui/embed_font.py from assets/fonts/AurebeshAF-Canon.otf\n"
        "-- (Aurebesh AF Canon, AurekFonts, CC-0). Do not edit by hand.\n"
        f'return "data:font/otf;base64,{data}"\n'
    )


def main(argv):
    text = render()
    if "--check" in argv:
        current = OUT.read_text(encoding="utf-8") if OUT.exists() else ""
        if current != text:
            print(f"{OUT.relative_to(ROOT)} is stale; run scripts/ui/embed_font.py")
            return 1
        print("font module up to date")
        return 0
    OUT.write_text(text, encoding="utf-8", newline="\n")
    print(f"wrote {OUT.relative_to(ROOT)} ({len(text)} bytes)")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
